-- evt:humble_ask
RegisterEvent(41, "Humble the Cleric", function(continueStep)
    local eventId = 41
    if continueStep == 1 then
        SetQBit(QBit(117361))
        evt.SetMonGroupBit(40, MonsterBits.Invisible, 1)
        evt.SimpleMessage("The screams of the unarmed cleric fill the tower as you quickly and efficiently dispatch him.")
        return
    end
    if continueStep == 2 then
        XeenQuests.hook("q-d6.humble")
        evt.SetMonGroupBit(40, MonsterBits.Invisible, 1)
        return
    end
    if continueStep ~= nil then
        return
    end
    if IsQBitSet(QBit(113124)) or IsQBitSet(QBit(117361)) then
        return
    end
    AskChoiceWithAnswerSteps(eventId, 3, "Oh, please don't kill me! I'm not like the others! I didn't want to mutiny against the High Priest! Slay him anyway?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Humble the Cleric")

